#!/usr/bin/env python3
import argparse, csv, json, sys
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP

def parse_args():
    parser = argparse.ArgumentParser(description='Reconcile payment transactions')
    parser.add_argument('--input', required=True, help='Path to transactions CSV file')
    return parser.parse_args()

def parse_timestamp(ts_str):
    # datetime.fromisoformat handles ISO 8601 with offsets
    try:
        return datetime.fromisoformat(ts_str)
    except Exception:
        # Fallback: strip Z and treat as UTC
        if ts_str.endswith('Z'):
            return datetime.fromisoformat(ts_str.rstrip('Z'))
        raise

def main():
    args = parse_args()
    tx_dict = {}  # tx_id -> (timestamp, amount, status)
    try:
        with open(args.input, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                tx_id = row['tx_id']
                ts = parse_timestamp(row['timestamp'])
                amount = Decimal(row['amount'])
                status = row['status'].strip().upper()
                # Keep the latest timestamp for each tx_id
                if tx_id in tx_dict:
                    if ts > tx_dict[tx_id][0]:
                        tx_dict[tx_id] = (ts, amount, status)
                else:
                    tx_dict[tx_id] = (ts, amount, status)
    except FileNotFoundError:
        print(f"Input file not found: {args.input}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error processing CSV: {e}", file=sys.stderr)
        sys.exit(1)

    total_valid = Decimal('0')
    valid_count = 0
    failed_count = 0
    for ts, amount, status in tx_dict.values():
        if status == 'VALID':
            total_valid += amount
            valid_count += 1
        else:
            failed_count += 1
    # Round to two decimal places
    total_valid = total_valid.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    result = {
        'total_valid_amount': str(total_valid),
        'valid_count': valid_count,
        'failed_count': failed_count
    }
    json.dump(result, sys.stdout)
    sys.stdout.write('\n')

if __name__ == '__main__':
    main()
